import java.io.*;

public class Main {
    static int rows, cols;
    static boolean[][] eligible;
    static int[][] match;
    static boolean[][] visited;

    static boolean augment(int r, int c) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols
                    || !eligible[nr][nc] || visited[nr][nc]) {
                continue;
            }

            visited[nr][nc] = true;
            if (match[nr][nc] == -1 || augment(match[nr][nc] / cols, match[nr][nc] % cols)) {
                match[nr][nc] = r * cols + c;
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        rows = fs.nextInt();
        cols = fs.nextInt();

        boolean[][] black = new boolean[rows][cols];
        int p = fs.nextInt();

        for (int i = 0; i < p; i++) {
            int r = fs.nextInt() - 1;
            int c = fs.nextInt() - 1;
            black[r][c] = true;
        }

        eligible = new boolean[rows][cols];
        int count = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (black[r][c]) continue;

                for (int k = 0; k < 4; k++) {
                    int nr = r + dr[k];
                    int nc = c + dc[k];
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && black[nr][nc]) {
                        eligible[r][c] = true;
                        count++;
                        break;
                    }
                }
            }
        }

        match = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                match[r][c] = -1;
            }
        }

        int matching = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (eligible[r][c] && (r + c) % 2 == 0) {
                    visited = new boolean[rows][cols];
                    if (augment(r, c)) matching++;
                }
            }
        }

        System.out.println(count - matching);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int ch;
            do {
                ch = read();
            } while (ch <= ' ');

            int value = 0;
            while (ch > ' ') {
                value = value * 10 + ch - '0';
                ch = read();
            }
            return value;
        }
    }
}
